def newton_carrier(values, lower_node, length):
    return sum(
        (-_sage_const_1 )**offset
        * binomial(lower_node + offset, offset)
        * binomial(lower_node + length + _sage_const_1 , length - offset)
        * values[lower_node + offset]
        for offset in range(length + _sage_const_1 )
    )


BLOCKS = (
    (_sage_const_200 , _sage_const_128 , _sage_const_63 , (_sage_const_139 , _sage_const_181 )),
    (_sage_const_272 , _sage_const_180 , _sage_const_63 , (_sage_const_191 , _sage_const_233 )),
    (_sage_const_300 , _sage_const_180 , _sage_const_57 , (_sage_const_191 , _sage_const_227 )),
    (_sage_const_321 , _sage_const_168 , _sage_const_53 , (_sage_const_179 , _sage_const_193 , _sage_const_211 )),
)


def audit_blocks():
    records = []
    for global_index, block_start, block_length, targets in BLOCKS:
        lower_node = block_start - _sage_const_1 
        stencil_nodes = range(
            lower_node, lower_node + block_length + _sage_const_1 
        )
        required_nodes = sorted(
            {
                node + displacement
                for node in stencil_nodes
                for displacement in (-_sage_const_1 , _sage_const_1 )
            }
        )
        moment_shells = {
            shift: shell_batch(global_index + shift, required_nodes)
            for shift in range(origin_operator.order() + _sage_const_1 )
        }
        z_values = {
            node: sum(
                ZZ(integer_coefficients[shift](n=global_index))
                * (
                    moment_shells[shift][node - _sage_const_1 ]
                    + moment_shells[shift][node + _sage_const_1 ]
                )
                for shift in range(origin_operator.order() + _sage_const_1 )
            )
            for node in stencil_nodes
        }
        old_values = shell_batch(global_index - _sage_const_1 , stencil_nodes)
        old_carrier = newton_carrier(
            old_values, lower_node, block_length
        )
        new_carrier = newton_carrier(
            z_values, lower_node, block_length
        )
        candidate_primes = list(
            prime_range(
                block_start + _sage_const_1 ,
                block_start + block_length + _sage_const_1 ,
            )
        )
        candidate_product = prod(candidate_primes)
        difference = (
            new_carrier
            - ZZ(multiplier(n=global_index)) * old_carrier
        )
        assert difference % candidate_product == _sage_const_0 
        quotient = difference // candidate_product
        target_product = prod(targets)
        assert gcd(old_carrier, quotient) == _sage_const_1 
        assert gcd(old_carrier, new_carrier) == target_product
        target_residues = tuple(
            (prime, quotient % prime) for prime in targets
        )
        assert all(residue != _sage_const_0  for _, residue in target_residues)
        records.append(
            (
                global_index,
                target_product,
                target_residues,
                (
                    abs(old_carrier).nbits(),
                    abs(new_carrier).nbits(),
                    abs(quotient).nbits(),
                ),
            )
        )
    return records


block_records = audit_blocks() if "--blocks" in sys.argv else []


def gcd_many(values):
    out = ZZ(_sage_const_0 )
    for value in values:
        out = gcd(out, abs(value))
    return out


def audit_cross_minors():
    records = []
    for global_index, D0, N0, targets in BLOCKS:
        moment = global_index - _sage_const_1 
        target_product = prod(targets)
        maximum_m = min(
            _sage_const_8 ,
            D0 - moment // _sage_const_2 ,
            moment - D0 - N0 + _sage_const_2 ,
        )
        lower = D0 - maximum_m + _sage_const_1 
        upper = D0 + N0 + maximum_m - _sage_const_2 
        nodes = list(range(lower, upper + _sage_const_1 ))
        required_nodes = list(range(lower - _sage_const_1 , upper + _sage_const_2 ))
        old_values = shell_batch(moment, nodes)
        moment_shells = {
            shift: shell_batch(global_index + shift, required_nodes)
            for shift in range(origin_operator.order() + _sage_const_1 )
        }
        new_values = {
            node: sum(
                ZZ(integer_coefficients[shift](n=global_index))
                * (
                    moment_shells[shift][node - _sage_const_1 ]
                    + moment_shells[shift][node + _sage_const_1 ]
                )
                for shift in range(origin_operator.order() + _sage_const_1 )
            )
            for node in nodes
        }

        history = []
        all_minor_gcd = ZZ(_sage_const_0 )
        for multiplicity in range(_sage_const_2 , maximum_m + _sage_const_1 ):
            length = N0 + multiplicity - _sage_const_2 
            d0 = D0 - multiplicity + _sage_const_1 
            old_carriers = [
                newton_carrier(old_values, d0 + shift, length)
                for shift in range(multiplicity)
            ]
            new_carriers = [
                newton_carrier(new_values, d0 + shift, length)
                for shift in range(multiplicity)
            ]
            primitive_minors = []
            for shift in range(multiplicity - _sage_const_1 ):
                prefactor = binomial(D0 + N0 + shift, length)
                determinant = (
                    old_carriers[shift] * new_carriers[shift + _sage_const_1 ]
                    - old_carriers[shift + _sage_const_1 ] * new_carriers[shift]
                )
                assert determinant % prefactor == _sage_const_0 
                primitive_minor = determinant // prefactor
                assert primitive_minor % target_product == _sage_const_0 
                primitive_minors.append(primitive_minor)
                all_minor_gcd = gcd(all_minor_gcd, abs(primitive_minor))
            minor_gcd = gcd_many(primitive_minors)
            assert minor_gcd % target_product == _sage_const_0 
            nuisance = minor_gcd // target_product
            history.append(
                (
                    multiplicity,
                    abs(nuisance).nbits(),
                    min(abs(value).nbits() for value in primitive_minors),
                    max(abs(value).nbits() for value in primitive_minors),
                )
            )
        coefficient_value_gcd = gcd_many(
            ZZ(coefficient(n=global_index))
            for coefficient in integer_coefficients
        )
        records.append(
            (
                global_index,
                (D0, N0),
                targets,
                maximum_m,
                tuple(history),
                nuisance,
                factor(nuisance),
                (
                    gcd(nuisance, ZZ(multiplier(n=global_index))),
                    gcd(nuisance, coefficient_value_gcd),
                    gcd(nuisance, ZZ(apery(global_index - _sage_const_1 ))),
                ),
                all_minor_gcd // target_product,
                factor(all_minor_gcd // target_product),
            )
        )
    return records


cross_minor_records = (
    audit_cross_minors() if "--cross-minors" in sys.argv else []
)


def guess_polynomial_recurrence(
    values,
    modulus,
    maximum_order,
    maximum_degree,
    holdout,
):
    field = GF(modulus)
    for order in range(_sage_const_1 , maximum_order + _sage_const_1 ):
        equation_count = len(values) - order
        for degree in range(maximum_degree + _sage_const_1 ):
            columns = (order + _sage_const_1 ) * (degree + _sage_const_1 )
            training_count = equation_count - holdout
            if training_count <= columns:
                continue
            rows = []
            for index in range(training_count):
                powers = [_sage_const_1 ]
                for _ in range(degree):
                    powers.append(powers[-_sage_const_1 ] * index % modulus)
                rows.append(
                    [
                        values[index + shift] * powers[power] % modulus
                        for shift in range(order + _sage_const_1 )
                        for power in range(degree + _sage_const_1 )
                    ]
                )
            kernel = matrix(field, rows).right_kernel()
            for candidate in kernel.basis():
                if all(
                    sum(
                        sum(
                            ZZ(candidate[
                                shift * (degree + _sage_const_1 ) + power
                            ])
                            * index**power
                            for power in range(degree + _sage_const_1 )
                        )
                        * values[index + shift]
                        for shift in range(order + _sage_const_1 )
                    )
                    % modulus
                    == _sage_const_0 
                    for index in range(training_count, equation_count)
                ):
                    return order, degree
    return None


def audit_ghost_recurrence_guess():
    global_index = _sage_const_400 
    modulus = _sage_const_1_000_000_007 
    nodes = list(range(global_index // _sage_const_2  + _sage_const_5 , global_index - _sage_const_1 ))
    required_nodes = list(range(nodes[_sage_const_0 ] - _sage_const_1 , nodes[-_sage_const_1 ] + _sage_const_2 ))
    old_values = shell_batch(
        global_index - _sage_const_1 , nodes, modulus=modulus
    )
    moment_shells = {
        shift: shell_batch(
            global_index + shift,
            required_nodes,
            modulus=modulus,
        )
        for shift in range(origin_operator.order() + _sage_const_1 )
    }
    multiplier_value = ZZ(multiplier(n=global_index)) % modulus
    w_values = [
        (
            sum(
                ZZ(integer_coefficients[shift](n=global_index))
                * (
                    moment_shells[shift][node - _sage_const_1 ]
                    + moment_shells[shift][node + _sage_const_1 ]
                )
                for shift in range(origin_operator.order() + _sage_const_1 )
            )
            - multiplier_value * old_values[node]
        )
        % modulus
        for node in nodes
    ]
    difference_order = _sage_const_60 
    ghost_values = list(w_values)
    for _ in range(difference_order):
        ghost_values = [
            (ghost_values[index + _sage_const_1 ] - ghost_values[index]) % modulus
            for index in range(len(ghost_values) - _sage_const_1 )
        ]
    return (
        len(w_values),
        guess_polynomial_recurrence(
            w_values, modulus, _sage_const_12 , _sage_const_10 , _sage_const_24 
        ),
        len(ghost_values),
        guess_polynomial_recurrence(
            ghost_values, modulus, _sage_const_12 , _sage_const_8 , _sage_const_16 
        ),
    )


ghost_guess_record = (
    audit_ghost_recurrence_guess()
    if "--guess-ghost" in sys.argv
    else None
)


def audit_generic_cross_gcds():
    rows = []
    for global_index in (_sage_const_80 , _sage_const_100 , _sage_const_120 , _sage_const_150 , _sage_const_180 , _sage_const_220 ):
        moment = global_index - _sage_const_1 
        D0 = (_sage_const_13  * global_index) // _sage_const_20 
        N0 = global_index // _sage_const_5 
        d0 = D0 - _sage_const_2 
        length = N0 + _sage_const_1 
        nodes = list(range(d0, d0 + length + _sage_const_3 ))
        required_nodes = list(range(nodes[_sage_const_0 ] - _sage_const_1 , nodes[-_sage_const_1 ] + _sage_const_2 ))
        old_values = shell_batch(moment, nodes)
        moment_shells = {
            shift: shell_batch(global_index + shift, required_nodes)
            for shift in range(origin_operator.order() + _sage_const_1 )
        }
        new_values = {
            node: sum(
                ZZ(integer_coefficients[shift](n=global_index))
                * (
                    moment_shells[shift][node - _sage_const_1 ]
                    + moment_shells[shift][node + _sage_const_1 ]
                )
                for shift in range(origin_operator.order() + _sage_const_1 )
            )
            for node in nodes
        }
        old_carriers = [
            newton_carrier(old_values, d0 + shift, length)
            for shift in range(_sage_const_3 )
        ]
        new_carriers = [
            newton_carrier(new_values, d0 + shift, length)
            for shift in range(_sage_const_3 )
        ]
        primitive_minors = []
        for shift in range(_sage_const_2 ):
            prefactor = binomial(d0 + shift + length + _sage_const_1 , length)
            determinant = (
                old_carriers[shift] * new_carriers[shift + _sage_const_1 ]
                - old_carriers[shift + _sage_const_1 ] * new_carriers[shift]
            )
            assert determinant % prefactor == _sage_const_0 
            primitive_minors.append(determinant // prefactor)
        common = gcd_many(primitive_minors)
        rows.append(
            (
                global_index,
                (D0, N0),
                abs(common).nbits(),
                factor(common),
                tuple(abs(value).nbits() for value in primitive_minors),
            )
        )
    return rows


